import React, { useState, useCallback, useEffect } from 'react';
import './Portfolio.css';

const eventCategories = [
  {
    key: 'batch',
    label: 'Batch Party',
    events: [
      {
        name: 'Batch 2023 Farewell',
        cover: '/GI_logo.png',
        photos: ['/GI_logo.png', '/GI_logo.png', '/GI_logo.png'],
        description: 'A memorable farewell for the 2023 batch.'
      },
      {
        name: 'Engineering Batch Bash',
        cover: '/GI_logo.png',
        photos: ['/GI_logo.png', '/GI_logo.png'],
        description: 'Celebrating the achievements of engineering graduates.'
      }
    ]
  },
  {
    key: 'social',
    label: 'Social Gatherings',
    events: [
      {
        name: 'Annual Club Meetup',
        cover: '/GI_logo.png',
        photos: ['/GI_logo.png', '/GI_logo.png', '/GI_logo.png'],
        description: 'Bringing together club members for a fun evening.'
      }
    ]
  },
  {
    key: 'birthday',
    label: 'Birthday Parties',
    events: [
      {
        name: 'Emma’s 18th Birthday',
        cover: '/GI_logo.png',
        photos: ['/GI_logo.png', '/GI_logo.png', '/GI_logo.png', '/GI_logo.png'],
        description: 'A vibrant birthday celebration for Emma.'
      }
    ]
  },
  {
    key: 'cultural',
    label: 'Cultural Events',
    events: [
      {
        name: 'Spring Festival',
        cover: '/GI_logo.png',
        photos: ['/GI_logo.png', '/GI_logo.png'],
        description: 'A colorful festival full of tradition and joy.'
      }
    ]
  },
  {
    key: 'other',
    label: 'Other Events',
    events: [
      {
        name: 'Product Launch 2024',
        cover: '/GI_logo.png',
        photos: ['/GI_logo.png', '/GI_logo.png', '/GI_logo.png'],
        description: 'Exciting new product launch event.'
      }
    ]
  }
];

const Portfolio = () => {
  const [selectedCategory, setSelectedCategory] = useState(eventCategories[0].key);
  const [selectedEvent, setSelectedEvent] = useState(null);
  const [lightboxIdx, setLightboxIdx] = useState(0);

  const category = eventCategories.find(cat => cat.key === selectedCategory);

  // Lightbox controls
  const openGallery = (event) => {
    setSelectedEvent(event);
    setLightboxIdx(0);
  };
  const closeGallery = () => {
    setSelectedEvent(null);
    setLightboxIdx(0);
  };
  const nextPhoto = useCallback(() => {
    if (!selectedEvent) return;
    setLightboxIdx(idx => (idx + 1) % selectedEvent.photos.length);
  }, [selectedEvent]);
  const prevPhoto = useCallback(() => {
    if (!selectedEvent) return;
    setLightboxIdx(idx => (idx - 1 + selectedEvent.photos.length) % selectedEvent.photos.length);
  }, [selectedEvent]);

  useEffect(() => {
    if (!selectedEvent) return;
    const handleKey = (e) => {
      if (e.key === 'Escape') closeGallery();
      if (e.key === 'ArrowRight') nextPhoto();
      if (e.key === 'ArrowLeft') prevPhoto();
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [selectedEvent, nextPhoto, prevPhoto]);

  return (
    <div className="portfolio-bg">
      <div className="portfolio-header">
        <h1>Event Portfolio</h1>
        <p>Browse our work by event category. Click a category, then an event to see its full gallery.</p>
      </div>
      <div className="portfolio-categories">
        {eventCategories.map(cat => (
          <button
            key={cat.key}
            className={`portfolio-category-tab${cat.key === selectedCategory ? ' active' : ''}`}
            onClick={() => setSelectedCategory(cat.key)}
          >
            {cat.label}
          </button>
        ))}
      </div>
      <div className="portfolio-event-grid">
        {category.events.map((event, idx) => (
          <div className="portfolio-event-card-pro" key={idx} onClick={() => openGallery(event)}>
            <div className="portfolio-event-card-imgwrap">
              <img src={event.cover} alt={event.name} className="portfolio-event-card-img" />
            </div>
            <div className="portfolio-event-card-info">
              <h3 className="portfolio-event-card-title">{event.name}</h3>
              <p className="portfolio-event-card-desc">{event.description}</p>
            </div>
          </div>
        ))}
      </div>
      {selectedEvent && (
        <div className="portfolio-lightbox" onClick={closeGallery}>
          <button className="portfolio-lightbox-close" onClick={closeGallery} aria-label="Close">&times;</button>
          <button className="portfolio-lightbox-nav left" onClick={e => { e.stopPropagation(); prevPhoto(); }} aria-label="Previous">&#8592;</button>
          <img
            src={selectedEvent.photos[lightboxIdx]}
            alt={selectedEvent.name + ' photo ' + (lightboxIdx+1)}
            className="portfolio-lightbox-img"
            onClick={e => e.stopPropagation()}
          />
          <button className="portfolio-lightbox-nav right" onClick={e => { e.stopPropagation(); nextPhoto(); }} aria-label="Next">&#8594;</button>
          <div className="portfolio-lightbox-caption">
            {selectedEvent.name} ({lightboxIdx+1}/{selectedEvent.photos.length})
          </div>
        </div>
      )}
    </div>
  );
};

export default Portfolio;
